const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { execFileSync } = require('node:child_process');
const { readEntries, validateEntries } = require('./build-icons.cjs');

const header =
  '// AUTO-GENERATED by scripts/build-icons.cjs --target harmony. Do not edit.\n';
const generatedDirectory = 'library/src/main/ets/generated';
const catalogDirectory = 'example/src/main/ets/generated';
const sha256 = (content) =>
  crypto.createHash('sha256').update(content).digest('hex');

function pathCommands(element) {
  if (element.kind === 'path') return element.d;
  if (element.kind === 'circle') {
    const { cx, cy, r } = element;
    return `M${cx - r} ${cy} A${r} ${r} 0 1 0 ${cx + r} ${cy} A${r} ${r} 0 1 0 ${cx - r} ${cy} Z`;
  }
  const { x, y, width, height } = element;
  // SVG clamps the two radii independently, even when only rx is supplied.
  const rx = Math.min(element.rx ?? 0, width / 2);
  const ry = Math.min(element.rx ?? 0, height / 2);
  if (rx === 0 || ry === 0)
    return `M${x} ${y} H${x + width} V${y + height} H${x} Z`;
  return `M${x + rx} ${y} H${x + width - rx} A${rx} ${ry} 0 0 1 ${x + width} ${y + ry} V${y + height - ry} A${rx} ${ry} 0 0 1 ${x + width - rx} ${y + height} H${x + rx} A${rx} ${ry} 0 0 1 ${x} ${y + height - ry} V${y + ry} A${rx} ${ry} 0 0 1 ${x + rx} ${y} Z`;
}

function buildHarmonyOutputs(entries, provenance) {
  const icons = validateEntries(entries);
  const outputs = new Map();
  const definitions = icons.map(({ component, def }) => ({
    iconName: component,
    strokeWidth: def.strokeWidth,
    elements: def.elements.map((element, index) => ({
      key: `${component}:${index}`,
      commands: pathCommands(element),
      hasFill: element.fill === 'currentColor',
      hasStroke: element.stroke !== 'none',
      alpha: element.opacity ?? 1,
    })),
  }));
  outputs.set(
    `${generatedDirectory}/UnifIconData.ets`,
    `${header}
export enum UnifIconName {
${icons.map(({ component }) => `  ${component} = '${component}'`).join(',\n')}
}

export interface UnifIconElement {
  key: string;
  commands: string;
  hasFill: boolean;
  hasStroke: boolean;
  alpha: number;
}

export interface UnifIconDefinition {
  iconName: string;
  strokeWidth: number;
  elements: UnifIconElement[];
}

const definitions: UnifIconDefinition[] = ${JSON.stringify(definitions, null, 2)};

export function getUnifIconDefinition(iconName: UnifIconName): UnifIconDefinition {
  const definition = definitions.find((item: UnifIconDefinition): boolean => item.iconName === iconName);
  if (definition === undefined) {
    throw new Error('Unknown icon: ' + iconName);
  }
  return definition;
}
`
  );
  for (const { component } of icons) {
    outputs.set(
      `${generatedDirectory}/${component}.ets`,
      `${header}
import { UnifIcon } from '../UnifIcon';
import { UnifIconName } from './UnifIconData';

@ComponentV2
export struct ${component} {
  @Param iconSize: number = 24;
  @Param iconColor: string = '#000';
  @Param lineWidth: number | undefined = undefined;
  @Param accessibilityLabel: string = '';

  build() {
    UnifIcon({
      iconName: UnifIconName.${component},
      iconSize: this.iconSize,
      iconColor: this.iconColor,
      lineWidth: this.lineWidth,
      accessibilityLabel: this.accessibilityLabel
    })
  }
}
`
    );
  }
  outputs.set(
    'library/Index.ets',
    `${header}
export { UnifIcon } from './src/main/ets/UnifIcon';
export { UnifIconName } from './src/main/ets/generated/UnifIconData';
${icons.map(({ component }) => `export { ${component} } from './src/main/ets/generated/${component}';`).join('\n')}
`
  );
  outputs.set(
    `${catalogDirectory}/IconCatalog.ets`,
    `${header}
import { UnifIconName } from '@unif/harmony-icons';

export const iconCatalog: UnifIconName[] = [
${icons.map(({ component }) => `  UnifIconName.${component}`).join(',\n')}
];
`
  );
  outputs.set(
    'library/src/main/resources/rawfile/icon-provenance.json',
    JSON.stringify(
      {
        generator:
          'react-native-icons/scripts/build-icons.cjs --target harmony',
        ...provenance,
        icons: icons.map(({ name, component }) => ({
          name,
          component,
          svgSha256: sha256(entries.find((entry) => entry.name === name).svg),
        })),
      },
      null,
      2
    ) + '\n'
  );
  return outputs;
}

function generateHarmony({ projectRoot, outputRoot, check = false }) {
  if (!outputRoot)
    throw new Error(
      'Harmony target requires --output <harmony-icons repository>'
    );
  const destination = path.resolve(outputRoot);
  let sourceRevision = 'uncommitted';
  try {
    sourceRevision = execFileSync('git', ['rev-parse', 'HEAD'], {
      cwd: projectRoot,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
  } catch {
    /* Fixtures and source archives still have per-file content hashes. */
  }
  const outputs = buildHarmonyOutputs(readEntries(projectRoot), {
    sourceRevision,
    manifestSha256: sha256(
      fs.readFileSync(path.join(projectRoot, 'scripts/icon-manifest.json'))
    ),
    generatorSha256: sha256(
      ['build-icons.cjs', 'build-harmony-icons.cjs', 'svg-parser.cjs']
        .map((file) => fs.readFileSync(path.join(__dirname, file), 'utf8'))
        .join('\n')
    ),
  });
  const stale = [generatedDirectory, catalogDirectory].flatMap((directory) => {
    const absolute = path.join(destination, directory);
    return fs.existsSync(absolute)
      ? fs
          .readdirSync(absolute)
          .map((file) => `${directory}/${file}`)
          .filter((file) => !outputs.has(file))
      : [];
  });
  const changed = [...outputs].filter(([file, content]) => {
    const absolute = path.join(destination, file);
    if (!fs.existsSync(absolute)) return true;
    const actual = fs.readFileSync(absolute, 'utf8');
    if (
      check &&
      file === 'library/src/main/resources/rawfile/icon-provenance.json'
    ) {
      try {
        const recorded = JSON.parse(actual);
        if (!/^(?:[a-f0-9]{40}|uncommitted)$/.test(recorded.sourceRevision))
          return true;
        const expected = JSON.parse(content);
        // Commits can differ while SVG, manifest and generator bytes remain identical.
        expected.sourceRevision = recorded.sourceRevision;
        content = JSON.stringify(expected, null, 2) + '\n';
      } catch {
        return true;
      }
    }
    return actual !== content;
  });
  if (check) {
    if (changed.length || stale.length)
      throw new Error(
        `Harmony generated icons are stale (${changed.length} changed, ${stale.length} removed)`
      );
    return outputs.size;
  }
  // Check ownership for every affected file before any write or removal.
  for (const file of [
    ...stale,
    ...changed
      .map(([changedFile]) => changedFile)
      .filter((changedFile) => changedFile.endsWith('.ets')),
  ]) {
    const absolute = path.join(destination, file);
    if (
      fs.existsSync(absolute) &&
      (!fs.statSync(absolute).isFile() ||
        !fs.readFileSync(absolute, 'utf8').startsWith(header))
    ) {
      throw new Error(
        `Refusing to replace or remove non-generated file: ${file}`
      );
    }
  }
  for (const [file, content] of changed) {
    const absolute = path.join(destination, file);
    fs.mkdirSync(path.dirname(absolute), { recursive: true });
    fs.writeFileSync(absolute, content);
  }
  for (const file of stale) fs.unlinkSync(path.join(destination, file));
  return outputs.size;
}

module.exports = { buildHarmonyOutputs, generateHarmony };
